const ASSETS={"/index.html":{"type":"text/html; charset=utf-8","body":"<!doctype html>\n<html lang=\"en\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>Garden of Flies</title><meta name=\"description\" content=\"Watch ten flies and their real on-chain economy.\"><link rel=\"stylesheet\" href=\"/observatory.css\"><script src=\"/observatory.js\" defer></script></head>\n<body><header><a href=\"/\">Garden of Flies</a><span id=\"connection\">Connecting to Robinhood Chain</span></header>\n<main><section class=\"intro\"><div><p class=\"eyebrow\">TEN FLIES · ONE ECONOMY</p><h1>Life in the garden.</h1><p>The garden runs itself. You’re here to watch.</p></div><div class=\"stamp\"><strong id=\"phase\">Checking the garden</strong><span id=\"updated\">Waiting for verified data</span></div></section>\n<section class=\"totals\"><div><label>ETH in the garden</label><strong id=\"eth\">Loading</strong></div><div><label>PONS held</label><strong id=\"pons\">Loading</strong></div><div><label>Confirmed transactions in recent feed</label><strong id=\"trades\">Loading</strong></div><div><label>Chain block</label><strong id=\"block\">Loading</strong></div></section>\n<section class=\"habitat\"><div class=\"section-head\"><h2>The inhabitants</h2><span>Actual wallets · actual balances</span></div><div id=\"flies\" class=\"flies\"><p>Reading the ten wallets from the chain…</p></div></section>\n<section class=\"bottom\"><div><div class=\"section-head\"><h2>Garden activity</h2><span id=\"round\">Waiting for the runner</span></div><div id=\"events\" class=\"events\"><p>No activity has been loaded yet.</p></div></div><aside><p class=\"eyebrow\">THE OUTSIDE MARKET</p><h2>PONS / ETH</h2><strong id=\"price\">Loading</strong><p>1% pool fee per swap. Values are read from the actual PONS/WETH pool.</p><a href=\"https://dexscreener.com/robinhood/0x10cc6bd38112cac182db90b6a71d8bb5939526ba\" target=\"_blank\" rel=\"noreferrer\">Open the market ↗</a><hr><h3>How this garden works</h3><p>Ten local neural instances observe real balances and select actions. Programmed limits govern execution. Visitors cannot start, stop, or trade for them.</p><p>Initial funding limit: 0.01 ETH total. Token exposure target: at most 50%. The runner must be online and safety checks must pass before a transaction can be sent.</p><p id=\"backup\">Checking wallet readiness.</p></aside></section>\n<p class=\"error\" id=\"error\" role=\"status\"></p><footer><span>Garden of Flies</span><span>Chain data refreshes automatically. Unavailable data is never replaced with simulation.</span></footer></main></body></html>\n"},"/observatory.js":{"type":"text/javascript; charset=utf-8","body":"'use strict';\nconst $=id=>document.getElementById(id);\nconst node=(tag,value,cls)=>{const n=document.createElement(tag);n.textContent=value;if(cls)n.className=cls;return n;};\nconst units=(s,d=6)=>(Number(s)/1e18).toLocaleString(undefined,{maximumFractionDigits:d,minimumFractionDigits:d});\nconst age=t=>Math.max(0,Math.floor(Date.now()/1000-t));\nconst phases={starting:'The garden is waking up',observing:'Observing the chain',waiting_for_backup:'Waiting for wallet backup',waiting_for_funding:'Waiting for funding',deploying:'Preparing the garden economy',running:'The garden is running',stopped:'The garden is paused for a safety check'};\nlet busy=false;\nasync function refresh(){\n if(busy)return;busy=true;\n try{\n  const r=await fetch('/api/status',{cache:'no-store'});if(!r.ok)throw Error('Live data is unavailable. Previously loaded values may be stale.');const d=await r.json();\n  const h=d.heartbeat,fresh=h&&age(h.observed_at)<360;\n  document.body.classList.remove('stale');$('error').textContent='';\n  $('connection').textContent='Connected to Robinhood Chain';$('block').textContent=d.block.toLocaleString();\n  $('updated').textContent='Chain checked '+new Date(d.observed_at*1000).toLocaleTimeString();\n  $('phase').textContent=fresh?phases[h.status]:'Runner offline or heartbeat unavailable';\n  $('round').textContent=fresh?'Measured neural round '+h.round:'No current runner heartbeat';\n  $('backup').textContent=h?(h.backup_ready?'Portable wallet backup verified.':'Wallet backup must be completed before funding.'):'Wallet readiness has not been reported.';\n  $('eth').textContent=units(d.wallets.reduce((n,w)=>n+BigInt(w.eth_wei),0n))+' ETH';\n  $('pons').textContent=units(d.wallets.reduce((n,w)=>n+BigInt(w.pons_units),0n),4)+' PONS';\n  $('price').textContent=units(d.market.price_wei,8)+' ETH / PONS';\n  $('trades').textContent=d.transactions.filter(t=>t.status==='confirmed').length;\n  $('flies').replaceChildren(...d.wallets.map(w=>{\n   const card=node('article','','fly'),portrait=node('div','🪰','portrait');portrait.setAttribute('aria-hidden','true');card.append(portrait,node('h3',w.name));\n   const link=node('a',w.address.slice(0,7)+'…'+w.address.slice(-5),'address');link.href='https://explorer.chain.robinhood.com/address/'+w.address;link.target='_blank';link.rel='noreferrer';card.append(link);\n   card.append(node('div',units(w.eth_wei)+' ETH','money'),node('div',units(w.pons_units,4)+' PONS','money'));\n   const t=h?.telemetry?.find(t=>t.id===w.id),brain=node('div','','neural');\n   brain.textContent=t&&age(t.measured_at)<600?`${t.firing.toLocaleString()} firing neurons · ${t.action.replaceAll('_',' ')} · measured ${age(t.measured_at)}s ago`:'No recent neural measurement';card.append(brain);return card;\n  }));\n  const names={deploy:'Garden deployment',buy_pons:'Bought PONS',sell_pons:'Sold PONS for ETH',approve_pons:'Approved an exact PONS exit',buy_resource:'Bought a resource',produce:'Produced resources',harvest:'Gathered resources'};\n  $('events').replaceChildren(...d.transactions.map(t=>{const row=node('div','','event'),left=node('div','');left.append(node('span',d.wallets[t.fly].name+' · '+(names[t.kind]||t.kind)),node('small',t.status+' · '+(t.block?'block '+t.block:'waiting for a receipt')));const a=node('a','View transaction ↗');a.href='https://explorer.chain.robinhood.com/tx/'+t.hash;a.target='_blank';a.rel='noreferrer';row.append(left,a);return row;}));\n  if(!d.transactions.length)$('events').append(node('p','No garden transactions have been submitted. This feed fills only with actual transaction hashes.'));\n }catch(error){document.body.classList.add('stale');$('connection').textContent='Chain connection unavailable';$('error').textContent=error.message;}finally{busy=false;}\n}\nrefresh();setInterval(refresh,20000);\n"},"/observatory.css":{"type":"text/css; charset=utf-8","body":":root{font-family:Arial,sans-serif;color:#233c2d;background:#f3f3e8;font-synthesis:none}*{box-sizing:border-box}body{margin:0}a{color:inherit}header{padding:24px 5%;display:flex;justify-content:space-between;align-items:center;border-bottom:1px solid #ccd4c2;gap:20px}header>a{font-family:Georgia,serif;font-size:25px;font-weight:bold;text-decoration:none}header>span{font-size:12px;color:#60745e}main{max-width:1400px;margin:auto;padding:38px 5%}.intro{display:flex;justify-content:space-between;align-items:end;gap:24px;margin-bottom:35px}.eyebrow{font-size:11px;letter-spacing:2px;font-weight:700}h1{font:normal clamp(36px,5vw,64px)/1.05 Georgia,serif;margin:12px 0}p{line-height:1.6;color:#5c6d59}.stamp{display:grid;gap:10px;padding-bottom:7px;text-align:right}.stamp strong{font-size:16px}.stamp span{font-size:12px;color:#67725f}.totals{display:grid;grid-template-columns:repeat(4,1fr);border:1px solid #cdd5c2;border-radius:12px;margin-bottom:35px;background:#fafaf1}.totals>div{padding:20px;border-right:1px solid #dce0d0}.totals>div:last-child{border:0}label{display:block;font-size:11px;line-height:1.5;color:#65745e;margin-bottom:9px}.totals strong{font-size:23px;font-weight:500}.section-head{display:flex;justify-content:space-between;align-items:center;gap:15px;margin-bottom:18px}h2{font:normal 24px Georgia,serif;margin:0}.section-head>span{font-size:11px;color:#6a7a64}.habitat{background:#e7eddc;border:1px solid #c9d4be;border-radius:18px;padding:25px}.flies{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:14px}.fly{min-width:0;background:#fbfcf3;border:1px solid #d4dcc8;border-radius:13px;padding:18px}.fly .portrait{font-size:28px;margin-bottom:12px;filter:grayscale(.2)}.fly h3{font:normal 23px Georgia,serif;margin:0 0 8px}.address{font:10px monospace;display:block;margin-bottom:18px;color:#778470;text-decoration:none}.money{font-size:16px;margin:8px 0}.money small{font-size:10px;color:#65745e}.neural{border-top:1px solid #e1e6d7;margin-top:16px;padding-top:12px;font-size:10px;line-height:1.7;color:#708167}.bottom{display:grid;grid-template-columns:2fr 1fr;gap:40px;margin-top:38px}.events{min-height:160px}.event{padding:16px 0;border-bottom:1px solid #dce0d1;display:flex;justify-content:space-between;gap:15px;font-size:13px}.event div{display:grid;gap:6px}.event small{font-size:10px;color:#6a7a65}.event a{font-size:11px}aside{border-left:1px solid #d0d8c3;padding-left:28px}aside p{font-size:12px}aside>strong{display:block;font-size:23px;margin-top:20px}aside>a{font-size:12px}hr{border:0;border-top:1px solid #d0d8c3;margin:25px 0}h3{font-weight:500}.error{color:#9a472d}.stale .totals,.stale .flies{opacity:.55}footer{margin-top:40px;padding-top:20px;border-top:1px solid #d0d8c3;display:flex;justify-content:space-between;gap:20px;font-size:11px;color:#78836d}@media(max-width:1000px){.flies{grid-template-columns:repeat(3,1fr)}}@media(max-width:650px){header{align-items:start;flex-direction:column;gap:7px}.intro{display:block}.stamp{text-align:left;margin-top:25px}.totals{grid-template-columns:repeat(2,1fr)}.totals strong{font-size:19px}.flies{grid-template-columns:repeat(2,1fr)}.habitat{padding:15px}.fly{padding:14px}.bottom{grid-template-columns:1fr;gap:25px}aside{border-left:0;border-top:1px solid #d0d8c3;padding:24px 0}.section-head{align-items:start;flex-direction:column;gap:8px}footer{flex-direction:column}.money{font-size:14px}}\r\n"}};
const WALLETS=[{"id":0,"name":"Clover","address":"0xcE6c65b9EcADe8e9CD7a87151DB80F1dAd1a6484"},{"id":1,"name":"Fig","address":"0x02165078E78eC3790e29FD99aF92591eD488CD82"},{"id":2,"name":"Juniper","address":"0x0593eB757714b72B92eA8BC1444fc23935Bf7E73"},{"id":3,"name":"Miso","address":"0x955b13045b1fb9B97fdf5F55260cC2033CD93436"},{"id":4,"name":"Olive","address":"0xd56bBf2d249E3608b31d0d4782957f28c087E1a3"},{"id":5,"name":"Pip","address":"0xbD6Fa8c38B7FC3AACb0c46c0F0B8d7119d21EeAC"},{"id":6,"name":"Sage","address":"0xd566A21DE02f55D17d38dE247254375659c3fafC"},{"id":7,"name":"Taro","address":"0xf03c39De73013C2862a2C73b48b65c47436dbDd9"},{"id":8,"name":"Willow","address":"0x70Bf4077c75338eCF2ADc9a748A2dc703dDc462C"},{"id":9,"name":"Zest","address":"0xdbFd0E2982795FF5fB33a05bf9Fc51dc722f1ca3"}];
// Read-only observatory plus authenticated, bounded runner telemetry ingestion.
// ASSETS and WALLETS are inserted by build-observatory.cjs; no keys are bundled.
const TOKEN='0x39dBED3a2bd333467115dE45665cC57F813C4571';
const POOL='0x10cc6bd38112cac182db90b6a71d8bb5939526ba';
let cached=null,cacheAt=0;
const headers={'content-type':'application/json','cache-control':'no-store','x-content-type-options':'nosniff'};
const json=(value,status=200)=>new Response(JSON.stringify(value),{status,headers});
async function rpc(env,method,params=[]){
 if(!env.GARDEN_RPC_URL)throw Error('Provider unavailable');
 const r=await fetch(env.GARDEN_RPC_URL,{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({jsonrpc:'2.0',id:1,method,params}),signal:AbortSignal.timeout(12000)});
 if(!r.ok)throw Error('Provider unavailable');const d=await r.json();if(d.error||d.result===undefined)throw Error('Chain read failed');return d.result;
}
async function authorized(request,env){
 const value=request.headers.get('authorization')||'';
 if(!env.GARDEN_PUBLISHER_KEY)return false;
 const hash=async x=>new Uint8Array(await crypto.subtle.digest('SHA-256',new TextEncoder().encode(x)));
 const [a,b]=await Promise.all([hash(value),hash('Bearer '+env.GARDEN_PUBLISHER_KEY)]);let result=0;for(let i=0;i<a.length;i++)result|=a[i]^b[i];return result===0;
}
async function ingest(request,env){
 if(!await authorized(request,env))return json({error:'Unauthorized'},401);
 if(Number(request.headers.get('content-length'))>65000)return json({error:'Too large'},413);
 const text=await request.text();if(text.length>65000)return json({error:'Too large'},413);
 const d=JSON.parse(text);
 if(!Number.isFinite(d.observed_at)||Math.abs(Date.now()/1000-d.observed_at)>120||!Number.isInteger(d.round)||d.round<0)return json({error:'Invalid heartbeat'},400);
 const statuses=['starting','observing','waiting_for_backup','waiting_for_funding','deploying','running','stopped'];
 if(!statuses.includes(d.status))return json({error:'Invalid status'},400);
 const telemetry=(d.telemetry||[]).slice(0,10).filter(t=>Number.isInteger(t.id)&&t.id>=0&&t.id<10&&Number.isFinite(t.measured_at)&&Number.isFinite(t.firing)&&t.firing>=0&&t.firing<=165122).map(t=>({id:t.id,measured_at:t.measured_at,firing:t.firing,neurons:t.neurons,action:String(t.action).slice(0,40),observation_block:t.observation_block}));
 const transactions=(d.transactions||[]).slice(0,20).filter(t=>/^0x[0-9a-f]{64}$/i.test(t.hash)&&Number.isInteger(t.fly)&&t.fly>=0&&t.fly<10).map(t=>({hash:t.hash,fly:t.fly,kind:String(t.kind).slice(0,40),created:t.created}));
 const body={observed_at:d.observed_at,status:d.status,round:d.round,backup_ready:d.backup_ready===true,enabled:d.enabled===true,
  error:d.error?'Runner paused after a safety or connection check':null,telemetry,transactions};
 await env.DB.prepare('INSERT INTO garden_heartbeat (id, observed, body) VALUES (1,?,?) ON CONFLICT(id) DO UPDATE SET observed=excluded.observed,body=excluded.body WHERE excluded.observed>garden_heartbeat.observed').bind(d.observed_at,JSON.stringify(body)).run();
 cached=null;return json({ok:true});
}
async function status(env){
 if(cached&&Date.now()-cacheAt<15000)return cached;
 if(BigInt(await rpc(env,'eth_chainId'))!==4663n)throw Error('Wrong chain');
 const block=await rpc(env,'eth_blockNumber');const head=Number(BigInt(block));
 const [stored,slot]=await Promise.all([env.DB.prepare('SELECT body FROM garden_heartbeat WHERE id=1').first(),rpc(env,'eth_call',[{to:POOL,data:'0x3850c7bd'},block])]);
 const heartbeat=stored?JSON.parse(stored.body):null;
 const sqrt=BigInt('0x'+slot.slice(2,66));if(sqrt<=0n)throw Error('Invalid market');
 const price=10n**18n*(2n**192n)/(sqrt*sqrt);
 const wallets=await Promise.all(WALLETS.map(async w=>{
  const [eth,token]=await Promise.all([rpc(env,'eth_getBalance',[w.address,block]),rpc(env,'eth_call',[{to:TOKEN,data:'0x70a08231'+w.address.slice(2).toLowerCase().padStart(64,'0')},block])]);
  return {...w,eth_wei:BigInt(eth).toString(),pons_units:BigInt(token).toString(),token_mark_wei:(BigInt(token)*(2n**192n)/(sqrt*sqrt)).toString()};
 }));
 const transactions=[];
 for(const t of heartbeat?.transactions||[]){
  const receipt=await rpc(env,'eth_getTransactionReceipt',[t.hash]);
  if(receipt&&receipt.from?.toLowerCase()!==WALLETS[t.fly].address.toLowerCase())continue;
  const confirmations=receipt?head-Number(BigInt(receipt.blockNumber))+1:0;
  transactions.push({...t,status:receipt?(BigInt(receipt.status)===0n?'reverted':confirmations>=12?'confirmed':'confirming'):'pending',confirmations,
   block:receipt?Number(BigInt(receipt.blockNumber)):null});
 }
 cached={observed_at:Date.now()/1000,block:head,chain_id:4663,wallets,market:{token:TOKEN,pool:POOL,price_wei:price.toString(),fee_bps:100},
  heartbeat,transactions,source:'Robinhood Chain RPC'};cacheAt=Date.now();return cached;
}
export default {async fetch(request,env){
 const path=new URL(request.url).pathname;
 try{
  if(path==='/api/heartbeat'&&request.method==='POST')return await ingest(request,env);
  if(request.method!=='GET')return json({error:'Read-only website'},405);
  if(path==='/api/status')return json(await status(env));
  const asset=ASSETS[path==='/'||path==='/pilot.html'?'/index.html':path];
  if(!asset)return json({error:'Not found'},404);
  return new Response(asset.body,{headers:{'content-type':asset.type,'cache-control':'no-cache','x-content-type-options':'nosniff',
   'content-security-policy':"default-src 'self'; script-src 'self'; style-src 'self'; img-src 'self' data:; connect-src 'self'; frame-ancestors 'none'"}});
 }catch{return json({error:'Live data is temporarily unavailable. No estimated balances are substituted.'},503);}
}};
